class FrequencyStack:
    def __init__(self):
        self.items = []                      # the plain stack, top at the end
        self.count = {}

    def push(self, x: int) -> None:
        self.items.append(x)
        self.count[x] = self.count.get(x, 0) + 1

    def pop(self) -> int:
        most = max(self.count.values())
        for i in range(len(self.items) - 1, -1, -1):   # walk down from the top
            x = self.items[i]
            if self.count[x] == most:
                del self.items[i]
                self.count[x] -= 1
                if not self.count[x]:
                    del self.count[x]
                return x


def run_stack(ops: list[list]) -> list:
    stack = FrequencyStack()
    return [getattr(stack, name)(*args) for name, *args in ops]
